SELECT DATE_TRUNC('MONTH', c.signup_date) AS signup_month, CASE WHEN c.credit_limit >= 15100 THEN 'high' WHEN c.credit_limit >= 7300 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, MIN(o.amount) AS min_amount FROM orders o INNER JOIN customers c ON o.customer_id = c.id WHERE c.is_active = TRUE GROUP BY DATE_TRUNC('MONTH', c.signup_date), CASE WHEN c.credit_limit >= 15100 THEN 'high' WHEN c.credit_limit >= 7300 THEN 'mid' ELSE 'low' END
